using Xunit;

namespace FrxEdit.Tests;

/// <summary>Needs no external forms: uses forms generated by create and the sample form in test_data.</summary>
public class VerificationTests
{
    private const string AddButton = """
        { "properties": { "CmdOne": { "$action": "add", "type": "CommandButton", "caption": "One", "leftPt": 5, "topPt": 5, "widthPt": 60, "heightPt": 20 } } }
        """;

    [Fact]
    public void Create_with_a_patch_reads_the_control_back()
    {
        using var workspace = new Workspace();
        var form = CreateFormWithButton(workspace);

        Assert.Contains(workspace.ReadControls(form), control => control.Name == "CmdOne");
    }

    [Fact]
    public void Build_stops_on_an_unknown_control_property()
    {
        using var workspace = new Workspace();
        var form = CreateFormWithButton(workspace);
        var output = workspace.PathOf("out/Test.frm");
        var patch = workspace.WritePatch("patch.json", """{ "properties": { "CmdOne": { "nonsense": 1 } } }""");

        var result = workspace.Run("build", form, patch, "--out", output, "--mode", "tolerant");

        Assert.Equal(2, result.ExitCode);
        Assert.Contains("nonsense", result.Error);
        Assert.False(File.Exists(output));
    }

    [Fact]
    public void Build_stops_on_an_unknown_form_property()
    {
        using var workspace = new Workspace();
        var form = CreateFormWithButton(workspace);
        var patch = workspace.WritePatch("patch.json", """{ "properties": { "Test": { "nonsense": 1 } } }""");

        var result = workspace.Run("build", form, patch, "--out", workspace.PathOf("out/Test.frm"), "--mode", "tolerant");

        Assert.Equal(2, result.ExitCode);
        Assert.Contains("nonsense", result.Error);
    }

    [Fact]
    public void Build_stops_on_a_misspelled_patch_field()
    {
        using var workspace = new Workspace();
        var form = CreateFormWithButton(workspace);
        var patch = workspace.WritePatch("patch.json", """{ "removes": ["CmdOne"] }""");

        var result = workspace.Run("build", form, patch, "--out", workspace.PathOf("out/Test.frm"), "--mode", "tolerant");

        Assert.NotEqual(0, result.ExitCode);
        Assert.Contains("removes", result.Error);
    }

    [Fact]
    public void Build_stops_when_a_readable_only_property_is_changed()
    {
        using var workspace = new Workspace();
        var patch = workspace.WritePatch("patch.json", """{ "properties": { "ScrollBar1": { "min": 12345 } } }""");

        var result = workspace.Run("build", SampleForm(), patch, "--out", workspace.PathOf("out/sample.frm"), "--mode", "tolerant");

        Assert.Equal(2, result.ExitCode);
        Assert.Contains("min", result.Error);
    }

    [Fact]
    public void Build_accepts_the_samples_inspect_output_as_a_patch()
    {
        using var workspace = new Workspace();
        var inspected = workspace.PathOf("inspect/layout.json");
        Directory.CreateDirectory(Path.GetDirectoryName(inspected)!);
        Assert.Equal(0, workspace.Run("inspect", SampleForm(), "--as-patch", "--mode", "tolerant", "--out", inspected).ExitCode);

        var result = workspace.Run("build", SampleForm(), inspected, "--out", workspace.PathOf("out/sample.frm"), "--mode", "tolerant");

        Assert.DoesNotContain("Unknown or unsupported property", result.Error);
    }

    [Fact]
    public void Failed_build_keeps_existing_output_and_leaves_no_staging_folder()
    {
        using var workspace = new Workspace();
        var form = CreateFormWithButton(workspace);
        var outputFolder = workspace.PathOf("out");
        Directory.CreateDirectory(outputFolder);
        var output = Path.Combine(outputFolder, "Test.frm");
        File.WriteAllText(output, "existing");
        var patch = workspace.WritePatch("patch.json", """{ "properties": { "CmdOne": { "tag": "lost" } } }""");

        var result = workspace.Run("build", form, patch, "--out", output, "--mode", "tolerant");

        Assert.Equal(2, result.ExitCode);
        Assert.Equal("existing", File.ReadAllText(output));
        Assert.Equal([output], Directory.GetFileSystemEntries(outputFolder));
    }

    [Fact]
    public void Control_check_accepts_what_the_patch_implies()
    {
        var patch = new PatchDocument
        {
            Remove = ["Gone"],
            Renames = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase) { ["Old"] = "New" },
            Add = [new AddControlPatch { Name = "Added" }],
        };

        BuildVerification.ThrowIfControlsDiffer(["Kept", "Gone", "Old"], patch, ["Kept", "New", "Added"]);
    }

    [Theory]
    [InlineData(new[] { "A" }, "Missing: [B]")]
    [InlineData(new[] { "A", "B", "C" }, "Unexpected: [C]")]
    [InlineData(new[] { "A", "B", "B" }, "Unexpected: [B]")]
    public void Control_check_reports_differences(string[] rebuilt, string expectedMessage)
    {
        var exception = Assert.Throws<CliException>(() =>
            BuildVerification.ThrowIfControlsDiffer(["A", "B"], null, rebuilt));

        Assert.Contains(expectedMessage, exception.Message);
    }

    [Fact]
    public void Failed_changes_are_only_those_the_patch_asked_for()
    {
        var patch = new PatchDocument
        {
            Layout = new Dictionary<string, LayoutPatch>(StringComparer.OrdinalIgnoreCase) { ["Moved"] = new LayoutPatch { TopPt = 3 } },
        };

        var failed = BuildVerification.FindFailedChanges(patch,
        [
            "<root>/Moved:CommandButton.top: 106 != 212",
            "<root>/Other:Label.width: 2540 != 1",
            "missing rebuilt control: Frame1/Gone:Label",
        ]);

        Assert.Equal(["<root>/Moved:CommandButton.top: 106 != 212", "missing rebuilt control: Frame1/Gone:Label"], failed);
    }

    private static string CreateFormWithButton(Workspace workspace)
    {
        var form = workspace.PathOf("Test.frm");
        var patch = workspace.WritePatch("create.json", AddButton);
        var result = workspace.Run("create", form, "--name", "Test", "--patch", patch);
        Assert.True(result.ExitCode == 0, result.Describe());
        return form;
    }

    private static string SampleForm()
    {
        var folder = new DirectoryInfo(AppContext.BaseDirectory);
        while (folder is not null && !File.Exists(Path.Combine(folder.FullName, "FrxEdit.sln")))
        {
            folder = folder.Parent;
        }

        Assert.NotNull(folder);
        return Path.Combine(folder.FullName, "test_data", "forms", "original", "userformallcontrol.frm");
    }
}
